/**
 * generate-source.ts
 *
 * Reads data/scraped.json + assets/svg-map.json and generates:
 *   - core/src/pictograms.generated.ts   (typed Pictogram registry)
 *   - react/src/{ComponentName}.tsx      (one React component per pictogram, plus props and index)
 *   - vue/src/{ComponentName}.ts         (one Vue component per pictogram, plus props and index)
 *   - elements/src/{ComponentName}.ts    (one custom element per pictogram, plus define helper and index)
 *
 * Generated files that no longer correspond to a pictogram are deleted.
 *
 * Run via: yarn generate
 */

import fs from 'fs';
import path from 'path';
import { optimize } from 'svgo';
import type { ScrapedData, ScrapedPictogram } from './scrape';
import type {
  Pictogram,
  PictogramCategory,
} from '../packages/@ghs-hazard-pictograms/core/src/types';
import { splitSvg, UID_PLACEHOLDER } from '../packages/@ghs-hazard-pictograms/core/src/svg';

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

/**
 * Converts a string to a URL-safe kebab-case slug.
 * @example slugify('GHS01: Explosive') // 'ghs01-explosive'
 */
const slugify = (str: string): string =>
  str
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '');

/**
 * Parses a pictogram title like "GHS01: Explosive" into its code and name parts.
 * Returns an empty code string for transport pictograms that have no GHS code.
 */
const parseTitle = (title: string): { code: string; name: string } => {
  const match = title.match(/^(GHS\d+):\s*(.+)$/i);
  if (match) return { code: match[1].toUpperCase(), name: match[2].trim() };
  return { code: '', name: title.trim() };
};

/** Pixel sizes at which raster variants are generated by create-assets.ts */
const IMAGE_SIZES = [240, 512, 768, 1024, 2048] as const;

/**
 * Builds the {@link Pictogram.assets} record for a pictogram given the relative
 * path to its original SVG file inside assets/.
 */
const buildAssets = (svgRelPath: string): Pictogram['assets'] => {
  const dir = path.dirname(svgRelPath);
  const base = path.basename(svgRelPath, path.extname(svgRelPath));

  const makeRecord = (ext: string): Record<number, string> =>
    Object.fromEntries(IMAGE_SIZES.map((s) => [s, `${dir}/${base}_${s}x${s}.${ext}`])) as Record<
      number,
      string
    >;

  return {
    jpg: makeRecord('jpg'),
    png: makeRecord('png'),
    svg: svgRelPath,
    webp: makeRecord('webp'),
  };
};

/**
 * Strips the XML declaration and DOCTYPE preamble from an SVG string so it
 * can be embedded inline in HTML without triggering parse errors.
 */
const cleanSvg = (svg: string): string =>
  svg
    .replace(/<\?xml[^>]*\?>/g, '')
    .replace(/<!DOCTYPE[^>]*>/g, '')
    .trim();

/**
 * Converts a kebab-case slug to PascalCase for use as a React component name.
 * @example toComponentName('ghs01-explosive') // 'Ghs01Explosive'
 */
const toComponentName = (id: string): string =>
  id
    .split('-')
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join('');

/**
 * Runs SVGO optimisation on the given SVG string and returns the optimised result.
 * Uses the default preset with multipass enabled.
 */
const optimizeSvg = (svg: string): string => {
  const result = optimize(svg, { multipass: true, plugins: ['preset-default'] });
  return result.data;
};

/**
 * Adds `viewBox="0 0 {width} {height}"` to the root `<svg>` when it has none.
 * Without a viewBox the drawing is clipped instead of scaled when a consumer
 * sets a width or height.
 */
const ensureViewBox = (svg: string): string =>
  svg.replace(/<svg\b([^>]*)>/, (tag, attrs: string) => {
    if (/\sviewBox="/.test(attrs)) return tag;
    const width = attrs.match(/\swidth="([\d.]+)(?:px)?"/);
    const height = attrs.match(/\sheight="([\d.]+)(?:px)?"/);
    if (!width || !height) {
      throw new Error(`SVG has neither a viewBox nor a numeric width/height: ${tag}`);
    }
    return `<svg${attrs} viewBox="0 0 ${width[1]} ${height[1]}">`;
  });

// ---------------------------------------------------------------------------
// Pictogram collection
// ---------------------------------------------------------------------------

interface PictogramEntry {
  /** The scraped pictogram data from Wikipedia. */
  category: PictogramCategory;
  /** The resolved SVG map key, or undefined when no matching file was found. */
  pictogram: ScrapedPictogram;
  /** Pictogram category used to populate {@link Pictogram.category}. */
  svgKey: string | undefined;
}

/**
 * Walks the scraped data and pairs each pictogram with its matching SVG key
 * from the SVG map (keyed by relative file path inside assets/).
 */
const collectEntries = (scraped: ScrapedData, svgMap: Record<string, string>): PictogramEntry[] => {
  const entries: PictogramEntry[] = [];
  const svgKeys = Object.keys(svgMap);

  /**
   * Finds the best matching SVG key for a pictogram by comparing base filenames.
   * Returns undefined when no match is found.
   */
  const findSvgKey = (imageUrls: string[]): string | undefined => {
    for (const url of imageUrls) {
      const filename = decodeURIComponent(path.basename(url)).replace(/^File:/, '');
      const filenameBase = path.basename(filename, path.extname(filename)).toLowerCase();
      const match = svgKeys.find(
        (k) => path.basename(k, path.extname(k)).toLowerCase() === filenameBase,
      );
      if (match) return match;
    }

    return undefined;
  };

  /** Processes a flat section of scraped pictogram data into {@link PictogramEntry} objects. */
  const processSection = (data: Record<string, ScrapedPictogram>, category: PictogramCategory) => {
    for (const [, pictogram] of Object.entries(data)) {
      if (!pictogram.images || pictogram.images.length === 0) continue;
      const svgKey = findSvgKey(pictogram.images);
      entries.push({ category, pictogram, svgKey });
    }
  };

  const topLevel: Array<[string, PictogramCategory]> = [
    ['Physical_hazards_pictograms', 'physical_hazards'],
    ['Health_hazards_pictograms', 'health_hazards'],
    ['Physical_and_health_hazard_pictograms', 'physical_and_health_hazards'],
    ['Environmental_hazards_pictograms', 'environmental_hazards'],
  ];

  for (const [key, cat] of topLevel) {
    const section = (scraped as Record<string, unknown>)[key] as {
      data: Record<string, ScrapedPictogram>;
    };
    if (section?.data) processSection(section.data, cat);
  }

  const transport = scraped.Transport_pictograms;
  for (const subKey of Object.keys(transport)) {
    const sub = (transport as Record<string, unknown>)[subKey] as {
      data: Record<string, ScrapedPictogram>;
    };
    if (sub?.data) processSection(sub.data, 'transport');
  }

  return entries;
};

// ---------------------------------------------------------------------------
// Code generation — src/pictograms.generated.ts
// ---------------------------------------------------------------------------

/** Returns the contents of the auto-generated pictogram registry file. */
const generatePictogramsFile = (pictograms: Pictogram[]): string => {
  const lines: string[] = [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `import type { Pictogram } from './types';`,
    ``,
    `export const pictograms: Pictogram[] = [`,
  ];

  for (const p of pictograms) {
    lines.push(
      `  {`,
      `    assets: {`,
      `      jpg: ${JSON.stringify(p.assets.jpg)},`,
      `      png: ${JSON.stringify(p.assets.png)},`,
      `      svg: ${JSON.stringify(p.assets.svg)},`,
      `      webp: ${JSON.stringify(p.assets.webp)},`,
      `    },`,
      `    category: ${JSON.stringify(p.category)},`,
      `    code: ${JSON.stringify(p.code)},`,
      `    description: ${JSON.stringify(p.description)},`,
      `    id: ${JSON.stringify(p.id)},`,
      `    name: ${JSON.stringify(p.name)},`,
      `    svg: ${JSON.stringify(p.svg)},`,
      `  },`,
    );
  }

  lines.push(`];`);
  return lines.join('\n') + '\n';
};

// ---------------------------------------------------------------------------
// Code generation — src/react/PictogramProps.ts
// ---------------------------------------------------------------------------

/** Returns the contents of the shared PictogramProps interface file. */
const generatePropsFile = (): string =>
  [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `import type * as React from 'react';`,
    ``,
    `/** Props accepted by every generated GHS pictogram React component. */`,
    `export interface PictogramProps {`,
    `  /** CSS class forwarded to the wrapping \`<span>\`. */`,
    `  className?: string;`,
    `  /** Accessible description injected as \`<desc>\` inside the SVG. Defaults to the Wikipedia hazard description. */`,
    `  description?: string;`,
    `  /** Height applied to the \`<svg>\` element (pixels or any CSS length). */`,
    `  height?: number | string;`,
    `  /** Inline styles forwarded to the wrapping \`<span>\`. */`,
    `  style?: React.CSSProperties;`,
    `  /** Accessible title injected as \`<title>\` inside the SVG. Defaults to the pictogram name. */`,
    `  title?: string;`,
    `  /** Width applied to the \`<svg>\` element (pixels or any CSS length). */`,
    `  width?: number | string;`,
    `  /** Labels the \`<svg>\` directly, replacing the \`aria-labelledby\` reference to its \`<title>\`/\`<desc>\`. */`,
    `  'aria-label'?: string;`,
    `}`,
    ``,
  ].join('\n');

// ---------------------------------------------------------------------------
// Code generation — shared pieces of every component file
// ---------------------------------------------------------------------------

interface ComponentEntry {
  /** Full hazard description. */
  description: string;
  /** Pictogram slug ID, e.g. "ghs01-explosive". */
  id: string;
  /** Human-readable pictogram name, e.g. "Explosive". */
  name: string;
  /** SVGO-optimised SVG string with a guaranteed viewBox. */
  optimizedSvg: string;
}

/** Escapes a string for embedding inside a template literal. */
const escTemplate = (s: string): string =>
  s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$/g, '\\$');

/**
 * Returns the module-level constants shared by the React, Vue and element
 * variants of a pictogram component, plus the template-literal snippet that
 * inserts the body with its IDs scoped to the instance's `uid`.
 */
const componentConstants = (entry: ComponentEntry): { lines: string[]; bodyExpr: string } => {
  const { attrs, body, height, width } = splitSvg(entry.optimizedSvg);
  return {
    lines: [
      `const _Attrs = \`${escTemplate(attrs)}\`;`,
      `const _Body = \`${escTemplate(body)}\`;`,
      `const _DefaultDesc = \`${escTemplate(entry.description)}\`;`,
      `const _DefaultTitle = '${entry.name.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}';`,
      `const _DefaultWidth = \`${escTemplate(width)}\`;`,
      `const _DefaultHeight = \`${escTemplate(height)}\`;`,
      `const _h = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/'/g, '&#39;').replace(/"/g, '&quot;');`,
    ],
    bodyExpr: body.includes(UID_PLACEHOLDER)
      ? `\${_Body.replaceAll('${UID_PLACEHOLDER}', uid)}`
      : `\${_Body}`,
  };
};

/**
 * Returns the statements (indented by `indent`) that build `svgHtml` from the
 * in-scope `uid`, `_w`, `_ht`, `resolvedTitle`, `resolvedDesc` and `ariaLabel`.
 */
const svgHtmlLines = (bodyExpr: string, indent: string): string[] =>
  [
    `const titleId = \`\${uid}--title\`;`,
    `const descId = \`\${uid}--desc\`;`,
    `const label = ariaLabel != null ? \`aria-label="\${_h(String(ariaLabel))}"\` : \`aria-labelledby="\${titleId} \${descId}"\`;`,
    `const svgHtml = \`<svg \${_Attrs} width="\${_w}" height="\${_ht}" role="img" \${label}>`,
  ]
    .map((l) => indent + l)
    .concat([
      `  <title id="\${titleId}">\${_h(resolvedTitle)}</title>`,
      `  <desc id="\${descId}">\${_h(resolvedDesc)}</desc>`,
      `  ${bodyExpr}</svg>\`;`,
    ]);

// ---------------------------------------------------------------------------
// Code generation — src/react/{ComponentName}.tsx
// ---------------------------------------------------------------------------

/** Returns the contents of one individual React component file. */
const generateComponentFile = (entry: ComponentEntry): string => {
  const componentName = toComponentName(entry.id);
  const { lines, bodyExpr } = componentConstants(entry);

  return [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `import * as React from 'react';`,
    `import type { PictogramProps } from './PictogramProps';`,
    ``,
    ...lines,
    ``,
    `export const ${componentName} = React.memo<PictogramProps>(({`,
    `  'aria-label': ariaLabel,`,
    `  className,`,
    `  description: resolvedDesc = _DefaultDesc,`,
    `  height,`,
    `  style,`,
    `  title: resolvedTitle = _DefaultTitle,`,
    `  width,`,
    `}) => {`,
    `  const uid = \`ghs-${entry.id}-\${React.useId().replace(/[^\\w-]/g, '')}\`;`,
    `  const _w = width !== undefined ? _h(String(width)) : _DefaultWidth;`,
    `  const _ht = height !== undefined ? _h(String(height)) : _DefaultHeight;`,
    ...svgHtmlLines(bodyExpr, '  '),
    `  return (`,
    `    <span`,
    `      className={className}`,
    `      dangerouslySetInnerHTML={{ __html: svgHtml }}`,
    `      style={{ display: 'contents', ...style }}`,
    `    />`,
    `  );`,
    `});`,
    `${componentName}.displayName = '${componentName}';`,
    ``,
  ].join('\n');
};

// ---------------------------------------------------------------------------
// Code generation — src/react/index.ts
// ---------------------------------------------------------------------------

/**
 * Returns the contents of the barrel index that re-exports all individual
 * component files along with shared types.
 */
const generateReactIndex = (componentNames: string[]): string =>
  [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `export type { PictogramProps } from './PictogramProps';`,
    `export { PictogramById } from './Pictogram';`,
    `export type { PictogramByIdProps } from './Pictogram';`,
    ...componentNames.map((name) => `export { ${name} } from './${name}';`),
    `export type { Pictogram, PictogramAssets, PictogramCategory } from '@ghs-hazard-pictograms/core';`,
    ``,
  ].join('\n');

// ---------------------------------------------------------------------------
// Code generation — Vue src/PictogramProps.ts
// ---------------------------------------------------------------------------

const generateVuePropsFile = (): string =>
  [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `import type { PropType } from 'vue';`,
    ``,
    `/**`,
    ` * Reusable Vue prop definitions shared by every generated GHS pictogram component.`,
    ` * An \`aria-label\` attribute, if given, labels the \`<svg>\` directly instead of its \`<title>\`/\`<desc>\`.`,
    ` */`,
    `export const pictogramProps = {`,
    `  /** Accessible description injected as \`<desc>\` inside the SVG. Defaults to the Wikipedia hazard description. */`,
    `  description: { type: String as PropType<string> },`,
    `  /** Height applied to the \`<svg>\` element (pixels or any CSS length). */`,
    `  height: { type: [Number, String] as PropType<number | string> },`,
    `  /** Accessible title injected as \`<title>\` inside the SVG. Defaults to the pictogram name. */`,
    `  title: { type: String as PropType<string> },`,
    `  /** Width applied to the \`<svg>\` element (pixels or any CSS length). */`,
    `  width: { type: [Number, String] as PropType<number | string> },`,
    `} as const;`,
    ``,
  ].join('\n');

// ---------------------------------------------------------------------------
// Code generation — Vue src/{ComponentName}.ts
// ---------------------------------------------------------------------------

/** Returns the contents of one individual Vue component file. */
const generateVueComponentFile = (entry: ComponentEntry): string => {
  const componentName = toComponentName(entry.id);
  const { lines, bodyExpr } = componentConstants(entry);

  return [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `import { defineComponent, h } from 'vue';`,
    `import { pictogramProps } from './PictogramProps';`,
    ``,
    ...lines,
    `let _instances = 0;`,
    ``,
    `export const ${componentName} = defineComponent({`,
    `  name: '${componentName}',`,
    `  inheritAttrs: false,`,
    `  props: {`,
    `    ...pictogramProps,`,
    `  },`,
    `  setup(props, { attrs }) {`,
    `    const uid = \`ghs-${entry.id}-\${++_instances}\`;`,
    `    return () => {`,
    `      const { 'aria-label': ariaLabel, style, ...rest } = attrs;`,
    `      const _w = props.width !== undefined ? _h(String(props.width)) : _DefaultWidth;`,
    `      const _ht = props.height !== undefined ? _h(String(props.height)) : _DefaultHeight;`,
    `      const resolvedTitle = props.title ?? _DefaultTitle;`,
    `      const resolvedDesc = props.description ?? _DefaultDesc;`,
    ...svgHtmlLines(bodyExpr, '      '),
    `      return h('span', { ...rest, style: [{ display: 'contents' }, style], innerHTML: svgHtml });`,
    `    };`,
    `  },`,
    `});`,
    ``,
  ].join('\n');
};

// ---------------------------------------------------------------------------
// Code generation — Vue src/index.ts
// ---------------------------------------------------------------------------

const generateVueIndex = (componentNames: string[]): string =>
  [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `export { pictogramProps } from './PictogramProps';`,
    `export { PictogramById } from './PictogramById';`,
    ...componentNames.map((name) => `export { ${name} } from './${name}';`),
    `export type { Pictogram, PictogramAssets, PictogramCategory } from '@ghs-hazard-pictograms/core';`,
    ``,
  ].join('\n');

// ---------------------------------------------------------------------------
// Code generation — elements src/{ComponentName}.ts
// ---------------------------------------------------------------------------

/** Returns the contents of one individual custom-element file. */
const generateElementFile = (entry: ComponentEntry): string => {
  const componentName = toComponentName(entry.id);
  const { lines, bodyExpr } = componentConstants(entry);

  return [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    ...lines,
    `let _instances = 0;`,
    ``,
    `export class ${componentName} extends HTMLElement {`,
    `  static readonly tagName = 'ghs-${entry.id}';`,
    `  static readonly observedAttributes = ['title', 'description', 'width', 'height', 'aria-label'];`,
    ``,
    `  private readonly _uid = \`ghs-${entry.id}-\${++_instances}\`;`,
    ``,
    `  connectedCallback(): void { this._render(); }`,
    `  attributeChangedCallback(): void { if (this.isConnected) this._render(); }`,
    ``,
    `  private _render(): void {`,
    `    const uid = this._uid;`,
    `    const _w = this.hasAttribute('width') ? _h(this.getAttribute('width')!) : _DefaultWidth;`,
    `    const _ht = this.hasAttribute('height') ? _h(this.getAttribute('height')!) : _DefaultHeight;`,
    `    const resolvedTitle = this.getAttribute('title') ?? _DefaultTitle;`,
    `    const resolvedDesc = this.getAttribute('description') ?? _DefaultDesc;`,
    `    const ariaLabel = this.getAttribute('aria-label');`,
    ...svgHtmlLines(bodyExpr, '    '),
    `    if (!this.style.display) this.style.display = 'contents';`,
    `    this.innerHTML = svgHtml;`,
    `  }`,
    `}`,
    ``,
  ].join('\n');
};

// ---------------------------------------------------------------------------
// Code generation — elements src/defineCustomElements.ts
// ---------------------------------------------------------------------------

const generateDefineCustomElements = (
  entries: Array<{ id: string; componentName: string }>,
): string =>
  [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `import { GhsPictogram } from './GhsPictogram';`,
    ...entries.map(({ componentName }) => `import { ${componentName} } from './${componentName}';`),
    ``,
    `const _elements: Array<[typeof HTMLElement & { tagName: string }, string]> = [`,
    `  [GhsPictogram, GhsPictogram.tagName],`,
    ...entries.map(({ componentName }) => `  [${componentName}, ${componentName}.tagName],`),
    `];`,
    ``,
    `/**`,
    ` * Registers all GHS hazard and ADR/UN transport pictogram custom elements.`,
    ` *`,
    ` * @param prefix — tag-name prefix (default \`"ghs"\`). Each element is registered`,
    ` *   as \`{prefix}-{id}\`, e.g. \`ghs-ghs01-explosive\` or \`ghs-division-2-3\`.`,
    ` *   Pass a custom string to avoid conflicts with other libraries. May be called`,
    ` *   several times with different prefixes.`,
    ` * @example`,
    ` * \`\`\`ts`,
    ` * import { defineCustomElements } from '@ghs-hazard-pictograms/elements';`,
    ` * defineCustomElements(); // registers ghs-ghs01-explosive, ghs-division-2-3, etc.`,
    ` * \`\`\``,
    ` */`,
    `export function defineCustomElements(prefix = 'ghs'): void {`,
    `  for (const [cls, defaultTag] of _elements) {`,
    `    const tag = prefix === 'ghs' ? defaultTag : \`\${prefix}-\${defaultTag.replace(/^ghs-/, '')}\`;`,
    `    if (customElements.get(tag)) continue;`,
    `    // A constructor can only be registered once, so other prefixes get their own subclass.`,
    `    customElements.define(tag, tag === defaultTag ? cls : class extends cls {});`,
    `  }`,
    `}`,
    ``,
  ].join('\n');

// ---------------------------------------------------------------------------
// Code generation — elements src/index.ts
// ---------------------------------------------------------------------------

const generateElementsIndex = (componentNames: string[]): string =>
  [
    `// THIS FILE IS AUTO-GENERATED. DO NOT EDIT MANUALLY.`,
    `// Run 'yarn generate' to regenerate.`,
    ``,
    `export { GhsPictogram } from './GhsPictogram';`,
    `export { defineCustomElements } from './defineCustomElements';`,
    ...componentNames.map((name) => `export { ${name} } from './${name}';`),
    `export type { Pictogram, PictogramAssets, PictogramCategory } from '@ghs-hazard-pictograms/core';`,
    ``,
  ].join('\n');

/**
 * Deletes auto-generated files in `dir` that were not written by this run,
 * e.g. components for pictograms that no longer exist upstream.
 */
const removeStaleGenerated = (dir: string, written: Set<string>): void => {
  for (const file of fs.readdirSync(dir)) {
    const full = path.join(dir, file);
    if (written.has(full) || !fs.statSync(full).isFile()) continue;
    if (fs.readFileSync(full, 'utf-8').startsWith('// THIS FILE IS AUTO-GENERATED.')) {
      fs.unlinkSync(full);
      console.log(`Removed stale: ${full}`);
    }
  }
};
// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

/**
 * Entry point for the code generator.
 * Reads cached scraped data and the SVG map, then writes all generated source files.
 *
 * Prereqs: run `yarn update` first to populate data/scraped.json and assets/svg-map.json.
 */
const generateSource = async (): Promise<void> => {
  const scrapedPath = path.join('data', 'scraped.json');
  const svgMapPath = path.join(
    'packages',
    '@ghs-hazard-pictograms',
    'assets',
    'assets',
    'svg-map.json',
  );

  if (!fs.existsSync(scrapedPath)) {
    throw new Error(`Missing ${scrapedPath}. Run 'yarn update' first.`);
  }

  if (!fs.existsSync(svgMapPath)) {
    throw new Error(`Missing ${svgMapPath}. Run 'yarn update' first.`);
  }

  const scraped: ScrapedData = JSON.parse(fs.readFileSync(scrapedPath, 'utf-8'));
  const svgMap: Record<string, string> = JSON.parse(fs.readFileSync(svgMapPath, 'utf-8'));

  console.log(`Loaded ${Object.keys(svgMap).length} SVGs from svg-map.json`);

  const entries = collectEntries(scraped, svgMap);
  console.log(`Collected ${entries.length} pictogram entries`);

  // Deduplicate by SVG key — GHS05 appears in both physical and physical+health sections.
  const seen = new Set<string>();
  const pictograms: Pictogram[] = [];
  const componentEntries: ComponentEntry[] = [];

  for (const { category, pictogram, svgKey } of entries) {
    const { code, name } = parseTitle(pictogram.title);
    const id = slugify(`${code ? `${code}-` : ''}${name}`);

    const dedupeKey = svgKey ?? id;
    if (seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);

    const svgContent = svgKey ? svgMap[svgKey] : '';
    if (!svgContent) {
      console.warn(`  Warning: no SVG found for "${pictogram.title}" (id: ${id})`);
      continue;
    }

    const assets = buildAssets(svgKey ?? `${id}/${id}.svg`);
    const description = (pictogram.copy ?? '').trim();

    const optimizedSvg = ensureViewBox(cleanSvg(optimizeSvg(svgContent)));

    pictograms.push({ assets, category, code, description, id, name, svg: optimizedSvg });
    componentEntries.push({ description, id, name, optimizedSvg });

    console.log(`  + ${id} (${category})`);
  }

  console.log(`\nGenerating source files for ${pictograms.length} pictograms...`);

  const written = new Set<string>();
  const write = (file: string, content: string): void => {
    fs.writeFileSync(file, content, 'utf-8');
    written.add(file);
  };

  // packages/@ghs-hazard-pictograms/core/src/pictograms.generated.ts
  const pictogramsOut = path.join(
    'packages',
    '@ghs-hazard-pictograms',
    'core',
    'src',
    'pictograms.generated.ts',
  );
  write(pictogramsOut, generatePictogramsFile(pictograms));
  console.log(`Written: ${pictogramsOut}`);

  // packages/@ghs-hazard-pictograms/react/src/ — individual component files, shared props, and barrel index
  const reactDir = path.join('packages', '@ghs-hazard-pictograms', 'react', 'src');
  fs.mkdirSync(reactDir, { recursive: true });

  const propsOut = path.join(reactDir, 'PictogramProps.ts');
  write(propsOut, generatePropsFile());
  console.log(`Written: ${propsOut}`);

  const componentNames: string[] = [];
  for (const entry of componentEntries) {
    const componentName = toComponentName(entry.id);
    componentNames.push(componentName);
    const componentOut = path.join(reactDir, `${componentName}.tsx`);
    write(componentOut, generateComponentFile(entry));
    console.log(`Written: ${componentOut}`);
  }

  const reactIndexOut = path.join(reactDir, 'index.ts');
  write(reactIndexOut, generateReactIndex(componentNames));
  console.log(`Written: ${reactIndexOut}`);

  // packages/@ghs-hazard-pictograms/vue/src/ — individual component files, shared props, and barrel index
  const vueDir = path.join('packages', '@ghs-hazard-pictograms', 'vue', 'src');
  fs.mkdirSync(vueDir, { recursive: true });

  const vuePropsOut = path.join(vueDir, 'PictogramProps.ts');
  write(vuePropsOut, generateVuePropsFile());
  console.log(`Written: ${vuePropsOut}`);

  const vueComponentNames: string[] = [];
  for (const entry of componentEntries) {
    const componentName = toComponentName(entry.id);
    vueComponentNames.push(componentName);
    const componentOut = path.join(vueDir, `${componentName}.ts`);
    write(componentOut, generateVueComponentFile(entry));
    console.log(`Written: ${componentOut}`);
  }

  const vueIndexOut = path.join(vueDir, 'index.ts');
  write(vueIndexOut, generateVueIndex(vueComponentNames));
  console.log(`Written: ${vueIndexOut}`);

  // packages/@ghs-hazard-pictograms/elements/src/ — individual element files, defineCustomElements helper, and barrel index
  const elementsDir = path.join('packages', '@ghs-hazard-pictograms', 'elements', 'src');
  fs.mkdirSync(elementsDir, { recursive: true });

  const elementEntries: Array<{ id: string; componentName: string }> = [];
  for (const entry of componentEntries) {
    const componentName = toComponentName(entry.id);
    elementEntries.push({ id: entry.id, componentName });
    const componentOut = path.join(elementsDir, `${componentName}.ts`);
    write(componentOut, generateElementFile(entry));
    console.log(`Written: ${componentOut}`);
  }

  const defineOut = path.join(elementsDir, 'defineCustomElements.ts');
  write(defineOut, generateDefineCustomElements(elementEntries));
  console.log(`Written: ${defineOut}`);

  const elementsIndexOut = path.join(elementsDir, 'index.ts');
  write(elementsIndexOut, generateElementsIndex(elementEntries.map((e) => e.componentName)));
  console.log(`Written: ${elementsIndexOut}`);

  for (const dir of [reactDir, vueDir, elementsDir]) removeStaleGenerated(dir, written);

  console.log('\nDone.');
};

// Run when executed directly via tsx (not when imported by update.ts).
const isMain =
  process.argv[1] &&
  (process.argv[1].endsWith('generate-source.ts') ||
    process.argv[1].endsWith('generate-source.js'));

if (isMain) {
  generateSource().catch((err) => {
    console.error(err);
    process.exit(1);
  });
}

export { generateSource };
